"use client";

import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import {
  AnimatePresence,
  motion,
  useMotionValueEvent,
  useScroll,
  useTransform,
} from "motion/react";

import { Celebration } from "./celebration";
import { EYFI_TIERS, type RewardTier } from "./tiers";
import "./reward-ladder.css";

export interface RewardLadderProps {
  /** The stages. Defaults to the EYFI Wave 01 ladder. */
  tiers?: RewardTier[];
  /**
   * How much scroll each stage gets, in vh. Lower = the ladder advances
   * faster under the same wheel travel.
   */
  stageScrollVh?: number;
  /**
   * `"scroll"` pins the section and scrubs through stages. `"static"`
   * renders every stage stacked, for docs, email, print — and it's what
   * reduced-motion users get automatically.
   */
  variant?: "scroll" | "static";
  /** Fire the Lottie burst when the crowning stage lands. Lazy-loaded. */
  celebrateAtMax?: boolean;
  /** Replacement Lottie JSON for the celebration. */
  celebrationData?: unknown;
  title?: ReactNode;
  subtitle?: ReactNode;
  className?: string;
}

const EASE_OUT = [0.16, 1, 0.3, 1] as const;
const SWAP = { duration: 0.46, ease: EASE_OUT } as const;

/** The stage and peek cards swap on the same choreography — enter from
 *  below, leave upward. The peek trails the stage by a beat. */
const swapMotion = (delay = 0) => ({
  initial: { opacity: 0, y: 28 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -20 },
  transition: { ...SWAP, delay },
});

const stageIndexLabel = (index: number, total: number) =>
  `${String(index + 1).padStart(2, "0")} / ${String(total).padStart(2, "0")}`;

const toneOf = (tier: RewardTier) => (tier.crowning ? "gold" : "lime");

const DEFAULT_TITLE = (
  <>
    Earned, <em>not handed.</em>
  </>
);

/** Portion of each stage's scroll segment spent holding on the threshold
 *  before the count starts climbing again. Gives the eye time to land. */
const DWELL = 0.34;

/** Where the last stage lands, as a fraction of the pinned scroll. The
 *  remaining tail is dwell on the crowning stage — without it the payoff
 *  (and the confetti) would arrive on the exact frame the pin releases. */
const CREST = 0.86;

export function RewardLadder({
  tiers = EYFI_TIERS,
  stageScrollVh = 78,
  variant = "scroll",
  celebrateAtMax = false,
  celebrationData,
  title = DEFAULT_TITLE,
  subtitle = "Scroll. Every stage is one you climbed to.",
  className,
}: RewardLadderProps) {
  const stages = useMemo(
    () => [...tiers].sort((a, b) => a.threshold - b.threshold),
    [tiers],
  );
  const max = stages[stages.length - 1]?.threshold ?? 0;
  const count = stages.length;

  const headingId = useId();
  const outerRef = useRef<HTMLDivElement | null>(null);

  /* Reduced motion is detected after mount so SSR and first paint agree —
   * branching on it during render would desync hydration. */
  const [prefersReduced, setPrefersReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setPrefersReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const isScroll = variant === "scroll" && !prefersReduced;

  /* ── scroll → registrations ──────────────────────────────── */
  const { scrollYProgress } = useScroll({
    target: outerRef,
    offset: ["start start", "end end"],
  });

  /* Each stage owns an equal slice of the scroll. Inside its slice the
   * count holds on the threshold for a beat, then climbs to the next one.
   * That's what makes the number feel like it's being earned rather than
   * linearly interpolated. */
  const [inputRange, outputRange] = useMemo(() => {
    const input: number[] = [];
    const output: number[] = [];
    const slice = CREST / Math.max(count - 1, 1);
    for (let i = 0; i < count; i += 1) {
      const start = i * slice;
      input.push(start);
      output.push(stages[i].threshold);
      if (i < count - 1) {
        input.push(start + slice * DWELL);
        output.push(stages[i].threshold);
      }
    }
    // Hold on the crowning stage for the remaining tail of the scroll.
    input.push(1);
    output.push(stages[count - 1]?.threshold ?? 0);
    return [input, output];
  }, [count, stages]);

  const registrations = useTransform(scrollYProgress, inputRange, outputRange);
  const rolled = useTransform(registrations, (v) =>
    Math.round(v).toLocaleString("en-IN"),
  );
  const railScale = useTransform(registrations, [0, max || 1], [0, 1]);

  /* activeIndex only changes at thresholds, so this setState fires a
   * handful of times per scroll-through — not once per frame. */
  const activeMotion = useTransform(registrations, (v) => {
    let index = 0;
    for (let i = 0; i < stages.length; i += 1) {
      if (v >= stages[i].threshold - 0.5) index = i;
    }
    return index;
  });

  const [active, setActive] = useState(0);
  useMotionValueEvent(activeMotion, "change", (v) => setActive(v));

  /* In static mode the scroll wiring is inert — pin the display at the top
   * stage so the section still reads as complete. */
  const activeIndex = isScroll ? active : 0;
  const activeTier = stages[activeIndex];
  const nextTier = stages[activeIndex + 1] ?? null;

  const [announcement, setAnnouncement] = useState("");
  const announced = useRef<string | null>(null);
  useEffect(() => {
    if (!isScroll || !activeTier || announced.current === activeTier.id) return;
    announced.current = activeTier.id;
    setAnnouncement(
      `${activeTier.label}, ${activeTier.threshold} registrations. ${activeTier.rewards.join(", ")}.`,
    );
  }, [activeTier, isScroll]);

  const showCelebration =
    celebrateAtMax && isScroll && activeTier?.crowning === true;

  /* ── static variant ──────────────────────────────────────── */
  if (!isScroll) {
    return (
      <section
        className={["rl", "rl--static", className].filter(Boolean).join(" ")}
        aria-labelledby={headingId}
      >
        <Header id={headingId} title={title} subtitle={subtitle} />
        <ol className="rl-static-list">
          {stages.map((tier, i) => (
            <li key={tier.id} className="rl-static-item" data-tone={toneOf(tier)}>
              <div className="rl-static-item__mark">
                <span className="rl-static-item__num">{tier.threshold}</span>
                <span className="rl-static-item__unit">
                  {tier.threshold === 0 ? "from day one" : "registrations"}
                </span>
              </div>
              <div className="rl-static-item__body">
                <p className="rl-stage__index">{stageIndexLabel(i, count)}</p>
                <h3 className="rl-stage__label">{tier.label}</h3>
                <RewardList rewards={tier.rewards} />
                {tier.note ? <p className="rl-stage__note">{tier.note}</p> : null}
              </div>
            </li>
          ))}
        </ol>
      </section>
    );
  }

  /* ── scroll variant ──────────────────────────────────────── */
  return (
    <section
      className={["rl", className].filter(Boolean).join(" ")}
      aria-labelledby={headingId}
    >
      <div
        ref={outerRef}
        className="rl-scroll"
        style={
          {
            "--rl-track": `${Math.max(count - 1, 1) * stageScrollVh}vh`,
          } as CSSProperties
        }
      >
        <div className="rl-pin">
          {/* Full-bleed rather than boxed into the card — the source file
           * is a pair of cannons firing across the frame. */}
          {showCelebration ? (
            <Celebration animationData={celebrationData} />
          ) : null}

          <div className="rl-pin__inner">
            <Header id={headingId} title={title} subtitle={subtitle} />

            <div className="rl-stack" aria-hidden="true">
              {/* the metric, as the hero object */}
              <div className="rl-count" data-tone={toneOf(activeTier)}>
                <motion.span className="rl-count__num">{rolled}</motion.span>
                <span className="rl-count__unit">registrations</span>
              </div>

              <div className="rl-stages">
                <div className="rl-stage-slot">
                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.article
                      key={activeTier.id}
                      className="rl-stage"
                      data-tone={toneOf(activeTier)}
                      {...swapMotion()}
                    >
                      <p className="rl-stage__index">
                        {stageIndexLabel(activeIndex, count)}
                      </p>
                      <h3 className="rl-stage__label">{activeTier.label}</h3>
                      {activeTier.blurb ? (
                        <p className="rl-stage__blurb">{activeTier.blurb}</p>
                      ) : null}
                      <RewardList rewards={activeTier.rewards} stagger />
                      {activeTier.note ? (
                        <p className="rl-stage__note">{activeTier.note}</p>
                      ) : null}
                    </motion.article>
                  </AnimatePresence>
                </div>

                {/* the next rung, dimmed — this is the pull */}
                <div className="rl-peek-slot">
                  <AnimatePresence mode="popLayout" initial={false}>
                    <motion.div
                      key={nextTier?.id ?? "__crest"}
                      className={
                        nextTier ? "rl-peek" : "rl-peek rl-peek--done"
                      }
                      {...swapMotion(0.06)}
                    >
                      {nextTier ? (
                        <>
                          <span className="rl-peek__tag">
                            Next · {nextTier.threshold}
                          </span>
                          <span className="rl-peek__label">
                            {nextTier.label}
                          </span>
                        </>
                      ) : (
                        <span className="rl-peek__label">
                          Top of the ladder.
                        </span>
                      )}
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>
            </div>

            {/* the rail advances itself — nothing to drag */}
            <div className="rl-rail" aria-hidden="true">
              <div className="rl-rail__track">
                <motion.div
                  className="rl-rail__fill"
                  style={{ scaleX: railScale }}
                />
                {stages.map((tier, i) => (
                  <span
                    key={tier.id}
                    className="rl-rail__tick"
                    data-reached={i <= activeIndex}
                    data-crowning={tier.crowning ? "true" : undefined}
                    style={
                      {
                        "--rl-at": `${(tier.threshold / (max || 1)) * 100}%`,
                      } as CSSProperties
                    }
                  >
                    <span className="rl-rail__dot" />
                    <span className="rl-rail__label">{tier.threshold}</span>
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* The visual layer above is aria-hidden — it only ever shows one
       * stage. This is the complete ladder, always, for screen readers. */}
      <ol className="rl-sr">
        {stages.map((tier) => (
          <li key={tier.id}>
            {tier.label} — {tier.threshold} registrations.{" "}
            {tier.rewards.join(", ")}.
          </li>
        ))}
      </ol>

      <p className="rl-sr" role="status" aria-live="polite">
        {announcement}
      </p>
    </section>
  );
}

function Header({
  id,
  title,
  subtitle,
}: {
  id: string;
  title: ReactNode;
  subtitle: ReactNode;
}) {
  return (
    <header className="rl-head">
      <h2 id={id} className="rl-head__title">
        {title}
      </h2>
      {subtitle ? <p className="rl-head__sub">{subtitle}</p> : null}
    </header>
  );
}

function RewardList({
  rewards,
  stagger = false,
}: {
  rewards: string[];
  stagger?: boolean;
}) {
  return (
    <ul className="rl-stage__rewards">
      {rewards.map((reward, i) => (
        <motion.li
          key={reward}
          className="rl-stage__reward"
          initial={stagger ? { opacity: 0, y: 10 } : false}
          animate={stagger ? { opacity: 1, y: 0 } : undefined}
          transition={{
            duration: 0.34,
            ease: EASE_OUT,
            delay: 0.14 + i * 0.07,
          }}
        >
          <span className="rl-stage__bullet" aria-hidden="true" />
          {reward}
        </motion.li>
      ))}
    </ul>
  );
}

export default RewardLadder;

/* Hallmark · component: reward-ladder · genre: atmospheric · theme: studied-DNA
 * interaction: scroll-scrubbed · one stage active, next stage dimmed
 * states: default · active · reached · crowning · reduced-motion · static
 * contrast: pass
 * ------------------------------------------------------------------
 * Every declaration resolves through `var(--token, fallback)`. Drop this
 * into a project that already defines the shadcn semantic tokens and the
 * host's values win; drop it into a bare project and the EYFI defaults
 * carry it. No raw colour is written below the token block.
 */

.rl {
  /* ── host tokens win, EYFI defaults as fallback ─────────── */
  --rl-bg: var(--background, #0a0a0a);
  --rl-border-strong: var(--border-strong, #2a2a2a);

  --rl-fg: var(--foreground, #ffffff);
  --rl-muted: var(--muted-foreground, #c8c8c4);
  --rl-muted-2: var(--muted-foreground-2, #8a8a85);
  --rl-muted-3: var(--muted-foreground-3, #4a4a4a);

  --rl-primary: var(--primary, #c4f62e);
  --rl-primary-rgb: var(--primary-rgb, 196 246 46);
  --rl-gold: var(--gold, #e8b923);
  --rl-gold-rgb: var(--gold-rgb, 232 185 35);

  --rl-font-display: var(
    --font-display,
    "Bricolage Grotesque",
    ui-sans-serif,
    system-ui,
    sans-serif
  );
  --rl-font-sans: var(
    --font-sans,
    "Space Grotesk",
    ui-sans-serif,
    system-ui,
    sans-serif
  );
  --rl-font-serif-italic: var(
    --font-serif-italic,
    "Instrument Serif",
    ui-serif,
    Georgia,
    serif
  );

  --rl-ease-out: var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  --rl-dur-fast: var(--dur-fast, 150ms);
  --rl-dur-mid: var(--dur-mid, 280ms);
  --rl-dur-slow: var(--dur-slow, 420ms);

  --rl-radius-card: var(--radius-card, 14px);
  --rl-radius-row: var(--radius-row, 12px);
  --rl-radius-pill: var(--radius-pill, 999px);

  color: var(--rl-fg);
  font-family: var(--rl-font-sans);
}

.rl *,
.rl *::before,
.rl *::after {
  box-sizing: border-box;
}

/* ══ the pin ════════════════════════════════════════════════ */

/* Tall parent + sticky child = the pin. No scroll library, no
 * ScrollTrigger; `useScroll` reads progress across exactly this range. */
.rl-scroll {
  position: relative;
  height: calc(var(--rl-track, 390vh) + 100svh);
}

.rl-pin {
  position: sticky;
  top: 0;
  height: 100svh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.rl-pin__inner {
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(1.25rem, 3.5vh, 2.5rem);
  padding-block: clamp(1.5rem, 5vh, 3rem);
}

/* ══ header ═════════════════════════════════════════════════ */

.rl-head {
  text-align: center;
}

.rl-head__title {
  font-family: var(--rl-font-display);
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.12;
  font-size: clamp(1.75rem, 4vw, 2.6rem);
  margin: 0 0 0.375rem;
  overflow-wrap: anywhere;
  min-width: 0;
}

.rl-head__title em {
  font-family: var(--rl-font-serif-italic);
  font-style: italic;
  font-weight: 400;
  color: var(--rl-primary);
}

.rl-head__sub {
  font-size: clamp(0.9375rem, 2vw, 1.0625rem);
  line-height: 1.55;
  color: var(--rl-muted-2);
  margin: 0;
}

/* ══ the stack: metric + stage + peek ═══════════════════════ */

.rl-stack {
  /* The two swapping boxes are a fixed size at every breakpoint. Sized to
   * the tallest stage so a 1-reward stage and a 3-reward stage occupy the
   * identical box — nothing under them ever moves. */
  --rl-stage-h: 20rem;
  --rl-peek-h: 3.5rem;

  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  align-items: center;
  gap: clamp(1.25rem, 4vw, 3.5rem);
}

/* the metric is the hero object — the coins were decoration, this is
 * the thing the ambassador is actually chasing */
.rl-count {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
  /* breathing room off the container's left edge, for both lines */
  padding-inline-start: clamp(0.75rem, 2.5vw, 2.5rem);
}

.rl-count__num {
  font-family: var(--rl-font-display);
  font-weight: 800;
  font-size: clamp(4rem, 13.5vw, 10rem);
  line-height: 0.84;
  letter-spacing: -0.045em;
  font-variant-numeric: tabular-nums;
  /* Reserve three digits so the unit label doesn't shuffle as the count
   * rolls 0 → 200. */
  min-width: 3ch;
  color: var(--rl-primary);
  transition: color var(--rl-dur-slow) var(--rl-ease-out);
}

.rl-count[data-tone="gold"] .rl-count__num {
  color: var(--rl-gold);
}

.rl-count__unit {
  margin-top: 0.625rem;
  font-size: 0.8125rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rl-muted-3);
}

.rl-stages {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-width: 0;
}

/* Entering and exiting cards share one grid cell so the swap never
 * shifts the layout underneath it. */
.rl-stage-slot,
.rl-peek-slot {
  display: grid;
}
.rl-stage-slot > *,
.rl-peek-slot > * {
  grid-area: 1 / 1;
}

.rl-stage-slot {
  height: var(--rl-stage-h);
}
.rl-peek-slot {
  height: var(--rl-peek-h);
}
.rl-stage-slot > *,
.rl-peek-slot > * {
  height: 100%;
}

/* ── the active stage ───────────────────────────────────── */

.rl-stage {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  border: 1px solid rgb(var(--rl-primary-rgb) / 0.4);
  background: rgb(var(--rl-primary-rgb) / 0.06);
  border-radius: var(--rl-radius-card);
  padding: clamp(1.125rem, 3vw, 1.75rem);
  min-width: 0;
  overflow: hidden;
}

/* Rewards take the slack so the note stays pinned to the bottom edge
 * regardless of how many reward lines a stage has. */
.rl-stage__rewards {
  flex: 1;
}

.rl-stage[data-tone="gold"] {
  border-color: rgb(var(--rl-gold-rgb) / 0.45);
  background: rgb(var(--rl-gold-rgb) / 0.07);
}

.rl-stage__index {
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--rl-muted-3);
  margin: 0 0 0.5rem;
  font-variant-numeric: tabular-nums;
}

.rl-stage__label {
  font-family: var(--rl-font-display);
  font-weight: 800;
  letter-spacing: -0.015em;
  line-height: 1.15;
  font-size: clamp(1.375rem, 3vw, 1.875rem);
  margin: 0;
  overflow-wrap: anywhere;
  min-width: 0;
}

.rl-stage__blurb {
  margin: 0.5rem 0 0;
  font-size: 0.9375rem;
  line-height: 1.55;
  color: var(--rl-muted);
}

.rl-stage__rewards {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-content: flex-start;
}

.rl-stage__reward {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--rl-fg);
  min-width: 0;
  overflow-wrap: anywhere;
}

.rl-stage__bullet {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  margin-top: 0.5rem;
  border-radius: 50%;
  background: var(--rl-primary);
}
.rl-stage[data-tone="gold"] .rl-stage__bullet {
  background: var(--rl-gold);
}

.rl-stage__note {
  font-family: var(--rl-font-serif-italic);
  font-style: italic;
  font-size: 0.9375rem;
  color: var(--rl-muted-2);
  margin: 0.875rem 0 0;
}

/* ── the next stage, diminished ─────────────────────────── */

.rl-peek {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1.125rem;
  border: 1px dashed var(--rl-border-strong);
  border-radius: var(--rl-radius-row);
  min-width: 0;
  overflow: hidden;
}

.rl-peek__tag {
  flex-shrink: 0;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rl-muted-3);
  font-variant-numeric: tabular-nums;
}

.rl-peek__label {
  font-family: var(--rl-font-display);
  font-weight: 700;
  font-size: 1rem;
  color: var(--rl-muted-3);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rl-peek--done .rl-peek__label {
  color: var(--rl-gold);
}
.rl-peek--done {
  border-style: solid;
  border-color: rgb(var(--rl-gold-rgb) / 0.3);
}

/* ══ the rail — advances itself ═════════════════════════════ */

.rl-rail {
  padding-inline: 1.25rem;
  padding-bottom: 1.5rem;
}

.rl-rail__track {
  position: relative;
  height: 3px;
  border-radius: var(--rl-radius-pill);
  background: var(--rl-border-strong);
}

.rl-rail__fill {
  position: absolute;
  inset: 0;
  border-radius: var(--rl-radius-pill);
  background: var(--rl-primary);
  transform-origin: left center;
  will-change: transform;
}

.rl-rail__tick {
  position: absolute;
  top: 50%;
  left: var(--rl-at);
  transform: translate(-50%, -50%);
  display: block;
}

.rl-rail__dot {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--rl-border-strong);
  outline: 3px solid var(--rl-bg);
  transition:
    background var(--rl-dur-mid) var(--rl-ease-out),
    transform var(--rl-dur-mid) var(--rl-ease-out);
}

.rl-rail__tick[data-reached="true"] .rl-rail__dot {
  background: var(--rl-primary);
}
.rl-rail__tick[data-reached="true"][data-crowning="true"] .rl-rail__dot {
  background: var(--rl-gold);
  transform: scale(1.35);
}

.rl-rail__label {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-top: 0.5rem;
  font-size: 0.6875rem;
  color: var(--rl-muted-3);
  font-variant-numeric: tabular-nums;
  transition: color var(--rl-dur-mid) var(--rl-ease-out);
}
.rl-rail__tick[data-reached="true"] .rl-rail__label {
  color: var(--rl-primary);
}
.rl-rail__tick[data-reached="true"][data-crowning="true"] .rl-rail__label {
  color: var(--rl-gold);
}

/* ══ celebration ════════════════════════════════════════════ */

.rl-celebration {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  overflow: hidden;
}
.rl-celebration > * {
  width: 100%;
  height: 100%;
}

/* ══ static variant ═════════════════════════════════════════ */

.rl--static {
  padding-block: clamp(2.5rem, 6vw, 4.5rem);
}

.rl-static-list {
  list-style: none;
  margin: clamp(1.5rem, 4vw, 2.5rem) 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.rl-static-item {
  display: grid;
  grid-template-columns: minmax(0, 6.5rem) minmax(0, 1fr);
  gap: clamp(1rem, 3vw, 2rem);
  align-items: start;
  padding: clamp(1rem, 2.5vw, 1.5rem);
  border: 1px solid rgb(var(--rl-primary-rgb) / 0.4);
  background: rgb(var(--rl-primary-rgb) / 0.06);
  border-radius: var(--rl-radius-card);
}
.rl-static-item[data-tone="gold"] {
  border-color: rgb(var(--rl-gold-rgb) / 0.45);
  background: rgb(var(--rl-gold-rgb) / 0.07);
}

.rl-static-item__num {
  display: block;
  font-family: var(--rl-font-display);
  font-weight: 800;
  font-size: clamp(2rem, 5vw, 2.75rem);
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--rl-primary);
  font-variant-numeric: tabular-nums;
}
.rl-static-item[data-tone="gold"] .rl-static-item__num {
  color: var(--rl-gold);
}

.rl-static-item__unit {
  display: block;
  margin-top: 0.375rem;
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rl-muted-3);
}

.rl-static-item__body {
  min-width: 0;
}

/* ══ screen-reader layer ════════════════════════════════════ */

.rl-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ══ responsive ═════════════════════════════════════════════ */

@media (max-width: 860px) {
  .rl-stack {
    --rl-stage-h: 22rem;
    grid-template-columns: minmax(0, 1fr);
    gap: 1rem;
    align-items: start;
  }

  .rl-count {
    flex-direction: row;
    align-items: baseline;
    gap: 0.75rem;
  }
  .rl-count__num {
    font-size: clamp(3.5rem, 19vw, 6rem);
  }
  .rl-count__unit {
    margin-top: 0;
  }
}

@media (max-width: 480px) {
  .rl-stack {
    --rl-stage-h: 23rem;
  }
  .rl-rail {
    padding-inline: 0.875rem;
  }
  .rl-rail__label {
    font-size: 0.625rem;
  }
  .rl-static-item {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }
}

/* Landscape phones and short laptops: the pin still has to fit 100svh.
 * Last in the cascade so it wins over the width rules above. */
@media (max-height: 760px) {
  .rl-head__sub {
    display: none;
  }
  .rl-count__num {
    font-size: clamp(3rem, 9vw, 5.5rem);
  }
  .rl-stage__blurb {
    display: none;
  }
  .rl-stack {
    --rl-stage-h: 15rem;
  }
}

@media (max-height: 560px) {
  .rl-stack {
    --rl-stage-h: 12rem;
    --rl-peek-h: 3rem;
  }
  .rl-stage__note {
    display: none;
  }
}

/* ══ reduced motion ═════════════════════════════════════════
 * The component swaps to the static variant in JS, so this is the
 * belt-and-braces pass for anything still animating. */
@media (prefers-reduced-motion: reduce) {
  .rl *,
  .rl *::before,
  .rl *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: var(--rl-dur-fast) !important;
  }
}

